import json,hashlib
D={'pages':[],'units':[],'boundary_notes':[],'review_notes':[],'completed':False};OUT='/workspace/scratch/volume4/batch539-548.json'
def save():json.dump(D,open(OUT,'w'),ensure_ascii=False,indent=2)
def p(n,rows):
 pars=[]
 for i,(ar,ru) in enumerate(rows,1):
  id=f'v4-p{n:03}-{i:02}';pars.append(dict(id=id,ar=ar,sha256=hashlib.sha256(ar.encode()).hexdigest(),witness='uploaded_2019_control_pdf',source_complete=True));D['units'].append(dict(id=id+'-ru',source_ids=[id],printed_pages=[n],ar=ar,ru=ru,draft_status='draft',print_collation='control_image_read',independent_human_review=False))
 D['pages'].append(dict(printed_page=n,pdf_leaf=n,witness_status='control_print_visually_read',publisher_footnote_text_imported=False,paragraphs=pars));save()
def merge(a,b):
 x=next(x for x in D['units'] if a in x['source_ids']);y=next(x for x in D['units'] if b in x['source_ids']);x['source_ids']+=y['source_ids'];x['printed_pages']+=y['printed_pages'];x['ar']+=' '+y['ar'];x['ru']+=' '+y['ru'];D['units'].remove(y);save()
p(539,[('التاسعة: أن يشهده فقره وضرورته إلى هذه الهداية فوق كل ضرورة.','Девятая: Он даёт ему увидеть свою нужду в этом руководстве и свою потребность в нём, превосходящую любую другую потребность.'),('العاشرة: أن يشهده الطريقين المنحرفين عن طريقها، وهما: طريق أهل الغضب الذين عدلوا عن اتباع الحق قصدا وعنادا، وطريق أهل الضلال الذين عدلوا عنها جهلا وضلالا.','Десятая: Он даёт ему увидеть два пути, отклонившихся от пути этого руководства. Это путь навлёкших гнев, которые отвернулись от следования истине намеренно и из упрямства, и путь заблудших, которые отвернулись от него по невежеству и заблуждению.'),('ثم يشهد جمع «الصراط المستقيم» في طريق واحد عليه جميع أنبياء الله ورسله وأتباعهم من الصديقين والشهداء والصالحين.','Затем он созерцает собранность «прямого пути» в одном пути, по которому следуют все пророки Аллаха, Его посланники и их последователи из правдивейших, мучеников и праведников.'),('فهذا هو الجمع الذي عليه رسل الله وأتباعهم، فمن حصل له هذا الجمع، فقد هدي إلى الصراط المستقيم.','Это и есть собранность, которой придерживаются посланники Аллаха и их последователи. Кто достиг этой собранности, тот направлен на прямой путь.'),('فصل','Раздел'),('قال الشيخ رحمه الله تعالى: (وأما التوحيد الثالث، فهو توحيد اختصه الحق لنفسه، واستحقه بقدره، وألاح منه لائحا إلى أسرار طائفة من صفوته، وأخرسهم عن نعته، وأعجزهم عن بثه).','Шейх, да помилует его Всевышний Аллах, сказал: «Что касается третьего единобожия, то это единобожие, которое Истинный оставил исключительно для Себя и которого достоин по Своему величию. Он явил его проблеск сокровенным глубинам группы Своих избранников, лишил их речи для его описания и сделал неспособными его передать».'),('فيقال: إما أن يريد بهذا التوحيد توحيد العبد لربه، وهو ما قام بالعبد من التوحيد؛ أو يريد به توحيد الرب لنفسه، وهو ما قام به من صفاته وكلامه.','Ответим: под этим единобожием он подразумевает либо единобожие раба по отношению к Господу — то, что присуще рабу, — либо единобожие Господа в отношении Самого Себя — присущие Ему атрибуты и речь.'),('فإن أردت به توحيد الرب لنفسه بنفسه، وهو علمه وكلامه وخبره','Если ты подразумеваешь единобожие Господа в отношении Самого Себя, осуществляемое Им Самим, — Его знание, речь и сообщение,')])
p(540,[('الذي يخبر به عن نفسه وصفاته، كقوله: {شَهِدَ اللَّهُ أَنَّهُ لَا إِلَهَ إِلَّا هُوَ} [آل عمران: 18]، وقوله: {إِنَّنِي أَنَا اللَّهُ لَا إِلَهَ إِلَّا أَنَا فَاعْبُدْنِي} [طه: 14]، وقوله: {هُوَ اللَّهُ الَّذِي لَا إِلَهَ إِلَّا هُوَ} [الحشر: 22]، ونحو ذلك= فذلك هو صفة الرب القائمة به كما يقوم به سائر صفاته من حياته، وعلمه، وقدرته، وإرادته، وسمعه وبصره. وذلك لا يفارق ذات الرب وينتقل إلى غيره، بل صفات المخلوق لا تفارقه وتنتقل إلى غيره، فكيف صفات الخالق!','которое Он сообщает о Себе и Своих атрибутах, например: {شَهِدَ اللَّهُ أَنَّهُ لَا إِلَهَ إِلَّا هُوَ} — «Аллах засвидетельствовал, что нет божества, кроме Него» [«Аль Имран», 3:18]; {إِنَّنِي أَنَا اللَّهُ لَا إِلَهَ إِلَّا أَنَا فَاعْبُدْنِي} — «Поистине, Я — Аллах. Нет божества, кроме Меня. Поклоняйся же Мне» [«Та Ха», 20:14]; {هُوَ اللَّهُ الَّذِي لَا إِلَهَ إِلَّا هُوَ} — «Он — Аллах, кроме Которого нет божества» [«Аль-Хашр», 59:22], — и тому подобное, то это атрибут Господа, присущий Ему, как и остальные Его атрибуты: жизнь, знание, могущество, воля, слух и зрение. Этот атрибут не покидает Сущность Господа и не переходит к другому. Даже свойства творения не покидают его и не переходят к другому; что же говорить об атрибутах Творца!'),('والله سبحانه يدل على ذلك بآياته القولية والفعلية، فيعلم عباده ما قام به من التوحيد لنفسه، بما دلهم عليه من قوله وفعله. فإذا شهد عبده له بما شهد به لنفسه، قيل: هذه الشهادة هي شهادة الرب، بمعنى: أنها مطابقة لها موافقة، لا بمعنى أنها عينها وأن الشهادتين واحدة بالعين. فما قام بقلب العبد إلا صفته وكلامه وخبره وإرادته، وهو غير ما قام بذات الرب من صفته وكلامه وخبره، وإن طابقه ووافقه.','Пречистый Аллах указывает на это Своими словесными и действенными знамениями. Он даёт рабам знать о присущем Ему утверждении единственности Самого Себя посредством того, на что указывают Его слова и действия. Если раб свидетельствует о Нём то же, что Он засвидетельствовал о Себе, можно сказать: «Это свидетельство — свидетельство Господа», имея в виду, что оно соответствует ему и согласуется с ним. Это не означает, что оно — само то свидетельство и что оба свидетельства численно тождественны. В сердце раба пребывают лишь его собственные свойство, речь, сообщение и воля. Это отличается от атрибута, речи и сообщения, присущих Сущности Господа, даже если соответствует им и согласуется с ними.'),('وعلى هذا فقوله: (اختصه الحق لنفسه) أي لا يوحده به غيره. وقوله: (واستحقه بقدره) أي استحقه بقدر كنهه الذي لا يبلغه غيره.','При таком понимании его слова «Которое Истинный оставил исключительно для Себя» означают: никто иной не исповедует Его единственность таким единобожием. Слова «Которого достоин по Своему величию» означают: Он достоин его сообразно Своей сокровенной сути, которой не достигает никто иной.'),('قوله: (وألاح منه لائحا إلى أسرار طائفة من صفوته)، أي أظهر منه شيئا يسيرا يسيرا إلى طائفة قليلة من الخلق، وهم أهل صفوته.','Его слова «Явил его проблеск сокровенным глубинам группы Своих избранников» означают: Он открыл самую малость из него немногим творениям — Своим избранникам.'),('وقوله: (أخرسهم عن نعته) يحتمل أن يريد به: أنه لا يقبل نعت المخلوقين كما لا يقبل لسان الأخرس الكلام؛ وعلى هذا فيكون نعته غير','Его слова «Лишил их речи для его описания» могут означать: оно не допускает описания творениями, как язык немого не допускает речи; при таком понимании описать его')])
p(541,[('ممكن. ويحتمل أن يريد به: أنه حال بينهم وبين نعته، لعجز السامع عن فهمه، فيكون نعته ممكنا، لكن الحق أسكتهم عنه غيرة عليه وصيانة له.','невозможно. Возможно и другое: Он преградил им путь к его описанию из-за неспособности слушателя понять его. Тогда описание возможно, но Истинный велел им молчать, ревниво оберегая и охраняя его.'),('قوله: (وأعجزهم عن بثه)، أي لم يقدرهم على الإخبار عنه.','Его слова «Сделал неспособными его передать» означают: не дал им возможности сообщать о нём.'),('فيقال: أفضل صفوة الرب تعالى: الأنبياء، وأفضلهم: الرسل، وأفضلهم: أولو العزم، وأفضلهم: الخليلان. والذي ألاحه الله إلى أسرارهم من ذلك هو أكمل توحيد عرفه العباد، ولا أكمل منه، وليس وراءه إلا الشطح والدعاوي والوساوس. وهم — صلوات الله وسلامه عليهم — قد تكلموا بالتوحيد ونعتوه وبينوه وأوضحوه وقرروه، بحيث صار في حيز التجلي والظهور والبيان. فعقلته القلوب، وحصلته الأفئدة، ونطقت به الألسن، وأوضحته الشواهد، وقامت عليه البراهين، ونادت عليه الدلائل. ولا يمكن أحدا أن ينقل عن نبي من الأنبياء ولا وارث نبي داع إلى ما دعا إليه أنه يعلم توحيدا لا يمكنه النطق به، وأن الله سبحانه أخرسه عن نطقه وأعجزه عن بثه. بل كل ما علمه القلب أمكن التعبير عنه، وإن اختلفت العبارة عنه ظهورا وخفاء وبين ذلك. وقد لا يفهمه إلا بعض الناس، فالناس كلهم لم تتفق أفهامهم لما جاءت به الرسل.','Ответим: лучшие из избранников Всевышнего Господа — пророки, лучшие из них — посланники, лучшие из них — обладающие твёрдой решимостью, а лучшие из них — два особых друга Аллаха. То, что Аллах открыл их сокровенным глубинам, — совершеннейшее единобожие, известное рабам. Нет ничего совершеннее; за его пределами лишь экстатические изречения, притязания и наущения. Они, да благословит их Аллах и приветствует, говорили о единобожии, описывали его, разъясняли, проясняли и утверждали его, так что оно стало явным, открытым и разъяснённым. Сердца поняли его, души усвоили его, языки произнесли его; свидетельства разъяснили его, доказательства утвердили его, и доводы возвестили о нём. Никто не может передать ни от одного пророка, ни от наследника пророка, призывающего к тому же, к чему призывал тот, что он знает единобожие, которое не может выразить, что Пречистый Аллах лишил его речи для его произнесения и сделал неспособным его передать. Напротив, всё, что узнало сердце, возможно выразить, хотя выражения различаются по ясности и неясности и занимают промежуточные степени. Иногда понять это способны лишь некоторые люди: понимание принесённого посланниками у людей неодинаково.'),('وكيف يقال: إن أعرف الخلق وأفصحهم وأنصحهم عاجز عن أن يبين ما عرفه الله من توحيده وأنه عاجز عن بثه؟ فما هذا التوحيد الذي عجزت الأنبياء والرسل عن بثه، ومنعوا من النطق به، وعرفه غيرهم؟','Как можно говорить, что самые знающие из творений, самые красноречивые и искреннейшие наставники неспособны разъяснить единобожие, которому Аллах их научил, и неспособны передать его? Что же это за единобожие, которое пророки и посланники не смогли передать, о котором им было запрещено говорить, но которое познали другие?'),('هذا كله إن أريد بهذا التوحيد التوحيد القائم بذات الحق تعالى لنفسه.','Всё это — если под таким единобожием понимается единобожие, присущее Сущности Всевышнего Истинного в отношении Самого Себя.')])
p(542,[('وإن أريد به التوحيد الذي هو صفة العبد وفعله لم يطابق قوله: (اختصه الرب لنفسه، واستحقه بقدره)، ولا يطابق القوافي الثلاثة التي أجاب بها الشيخ عنه، وأن توحيده نفسه هو التوحيد لا غيره.','Если же подразумевается единобожие как свойство и действие раба, это не согласуется со словами «Господь оставил его исключительно для Себя и достоин его по Своему величию», а также с тремя стихотворными строками, которыми шейх ответил об этом: что единобожие — лишь Его собственное утверждение единственности Себя, и ничто иное.'),('وأيضا: فصفة العبد وفعله لا يعجز عن بثها، ولا يخرس عن النطق بها. وكل ما قام بالعبد فإنه يمكنه التعبير عنه وكشفه وبيانه.','Кроме того, человек не бывает неспособен передать собственное свойство и действие и не лишается речи, когда надо рассказать о них. Всё, что присуще рабу, он способен выразить, раскрыть и разъяснить.'),('فإن قيل: المراد بذلك أن الرب تعالى في الحقيقة هو الموحد لنفسه في قلوب صفوته، لا أنهم هم الموحدون. ولهذا قال الشيخ: (والذي يشار إليه على ألسن المشيرين: أنه إسقاط الحدث وإثبات القدم) وعليه أنشد هذه القوافي الثلاثة:','Если скажут: «Подразумевается, что на самом деле Всевышний Господь Сам утверждает Свою единственность в сердцах Своих избранников, а не они исповедуют Его единственность. Поэтому шейх сказал: “То, на что указывают языки указывающих, — устранение возникшего и утверждение предвечного”». По этому поводу он произнёс три стихотворные строки:'),('ما وحد الواحد من واحد إذ كل من وحده جاحد\nتوحيد من ينطق عن نعته عارية أبطلها الواحد\nتوحيده إياه توحيده ونعت من ينعته لاحد','Никто из единых не исповедал единственности Единого:\nВедь всякий, кто исповедал Его единственность, — отрицающий.\nЕдинобожие того, кто говорит о Его описании, —\nОдолженная вещь, которую Единый отверг.\nЕго утверждение единственности Самого Себя — Его единобожие,\nА описание описывающего Его — уклонение.'),('فقوله: (ما وحد الواحد من واحد)، يعني: ما وحد الله عز وجل أحد سواه، وكل من وحده فهو جاحد لحقيقة توحيده، فإن توحيده يتضمن شهود ذات الموحد وفعله وما قام به من التوحيد، وشهود ذات الواحد وانفراده، وتلك اثنينية ظاهرة؛ بخلاف توحيده لنفسه، فإنه يكون هو الموحد والموحد، والتوحيد صفته وكلامه القائم به، فما ثم غيره، فلا اثنينية ولا تعدد.','Его слова «Никто из единых не исповедал единственности Единого» означают: никто, кроме Самого Аллаха, Велик Он и Могуч, не исповедал Его единственности. Всякий, кто это делает, отрицает подлинную суть Его единобожия, поскольку его единобожие предполагает созерцание сущности исповедующего единственность, его действия и присущего ему единобожия, а также созерцание Сущности Единого и Его исключительности. Это явная двойственность. Иначе обстоит дело, когда Он утверждает единственность Самого Себя: Он и Утверждающий единственность, и Тот, Чья единственность утверждается; единобожие — Его свойство и присущая Ему речь. Там нет никого иного, а значит, нет ни двойственности, ни множественности.')])
p(543,[('وأيضا، فمن وحده من الخلق فلا بد أن يصفه بصفة، وذلك يتضمن جحد حقه الذي هو عدم انحصاره تحت الأوصاف. فمن وصفه فقد جحد إطلاقه عن قيود الصفات.','Кроме того, кто из творений исповедует Его единственность, неизбежно описывает Его каким-либо свойством. Это предполагает отрицание Его права — не быть ограниченным описаниями. Кто описал Его, тот отрицает Его свободу от ограничений атрибутами.'),('وقوله:','Его слова:'),('(توحيد من ينطق عن نعته عارية أبطلها الواحد)','«Единобожие того, кто говорит о Его описании, —\nОдолженная вещь, которую Единый отверг».'),('يعني: توحيد الناطقين عنه عارية مردودة كما تسترد العواري، إشارة إلى أن توحيدهم ليس ملكا لهم، بل الحق أعارهم إياه، كما يعير المعير متاعه لغيره ينتفع به، ويكون ملكا للمعير لا للمستعير.','Это означает: единобожие говорящих о Нём — одолженная вещь, возвращаемая, как возвращают вещи, взятые во временное пользование. Это указание на то, что их единобожие не является их собственностью: Истинный дал им его в пользование, подобно тому как владелец даёт другому свою вещь, чтобы тот пользовался ею. Собственность остаётся за давшим, а не за взявшим.'),('وقوله: (أبطلها الواحد)، أي: الواحد المطلق من كل الوجوه وحدته تبطل هذه العارية وتردها إلى مالكها الحق، فإن الوحدة المطلقة من جميع الوجوه تنافي ملك الغير لشيء من الأشياء، بل الملك لتلك العارية هو الواحد فقط، فلذلك أبطلت الوحدة هذه العارية.','Его слова «Которую Единый отверг» означают: единство Того, Кто безусловно един со всех сторон, отменяет это временное владение и возвращает вещь её истинному Владельцу. Безусловное единство со всех сторон исключает, чтобы кто-либо иной владел хоть чем-либо. Владелец одолженного — лишь Единый. Поэтому единство отменило это временное владение.'),('قوله: (توحيده إياه توحيده)، أي: توحيده الحقيقي هو توحيده لنفسه بنفسه، من غير أثر للسوى بوجه، بل لا سوى هناك.','Его слова «Его утверждение единственности Самого Себя — Его единобожие» означают: Его подлинное единобожие — утверждение Им Самим Своей единственности, без какого-либо влияния иного. Более того, там вообще нет иного.'),('وقوله: (ونعت من ينعته لاحد)، أي: نعت الناعت له إلحاد، وهو عدول عما يستحقه من كمال التوحيد، فإنه أسند إلى نزاهة الحق ما لا يليق به إسناده، فإن عين الأزلية تأبى نطق الحدث، ومحض التوحيد يأبى أن يكون للسوى أثر البتة.','Его слова «А описание описывающего Его — уклонение» означают: описание, которое даёт описывающий, — уклонение от подобающего Ему совершенного единобожия. Описывающий приписал чистоте Истинного то, чего не подобает Ему приписывать. Ведь сама предвечность отвергает речь возникшего, а чистое единобожие отвергает какое-либо влияние иного вообще.')])
merge('v4-p539-08','v4-p540-01');merge('v4-p540-05','v4-p541-01')
p(544,[('فيقال — وبالله التوفيق —: في هذا الكلام من الإجمال والحق والإلحاد ما لا يخفى!','Ответим, и успех дарует Аллах: в этих словах есть очевидная смесь неопределённых выражений, истины и безбожия!'),('فأما قوله: «إن الرب تعالى هو الموحد لنفسه في قلوب صفوته، لا أنهم هم الموحدون»، إن أريد به ظاهره، وأن الموحد لله هو الله لا غيره، وأن الله سبحانه حل في صفوته، حتى وحد نفسه، فيكون هو الموحد لنفسه في قلوب أوليائه، لاتحاده بهم أو حلوله فيهم= فهذا قول النصارى بعينه، بل هو شر منه؛ لأنهم خصوه بالمسيح، وهؤلاء عموا به كل موحد. بل عند الاتحادية: الموحد والموحد واحد، وما ثم تعدد في الحقيقة.','Если слова «Всевышний Господь Сам утверждает Свою единственность в сердцах Своих избранников, а не они исповедуют Его единственность» понимать буквально — что единственность Аллаха утверждает только Аллах, что Пречистый Аллах вселился в Своих избранников, чтобы утвердить единственность Самого Себя, и что Он делает это в сердцах Своих приближённых благодаря единению с ними или вселению в них, — то это в точности слова христиан. Более того, это хуже их слов: они ограничили это Мессией, а эти распространили на каждого единобожника. У сторонников единения Утверждающий единственность и Тот, Чья единственность утверждается, — одно, и в действительности никакой множественности нет.'),('وإن أريد به أنه هو الذي وفقهم لتوحيده، وألهمهم إياه، وجعلهم يوحدونه، فهو الموحد لنفسه بما عرفهم به من توحيده، وألقاه في قلوبهم وأجراه على ألسنتهم= فهذا المعنى صحيح، ولكن لا يصح نفي أفعالهم عنهم، فلا يقال: إن الله هو الموحد لنفسه، لا أن عبده يوحده. هذا باطل شرعا وعقلا وحسا، بل الحق أن يقال: إن الله سبحانه وحد نفسه بتوحيد قام به، ووحده عبيد بتوحيد قام بهم بإذنه ومشيئته وتوفيقه. فهو الموحد لنفسه بنفسه، وهم الموحدون له بتوفيقه ومعونته وإذنه.','Если же подразумевается, что Он даровал им возможность исповедовать Его единственность, внушил им это и сделал их единобожниками, так что Он утверждает единственность Самого Себя посредством того единобожия, которому их научил, которое вложил в их сердца и заставил произносить их языки, — такой смысл верен. Однако нельзя отрицать, что их действия принадлежат им. Нельзя говорить: «Аллах Сам утверждает Свою единственность, а Его раб не исповедует её». Это ложно по Закону, разуму и чувственному восприятию. Верно же сказать: Пречистый Аллах утвердил Свою единственность единобожием, присущим Ему, а рабы исповедовали Его единственность единобожием, присущим им, по Его дозволению, воле и содействию. Он Сам утверждает единственность Самого Себя, а они исповедуют Его единственность благодаря Его содействию, помощи и дозволению.'),('فالذي قام بهم ليس هو الرب تعالى ولا وصفه، بل العلم به ومحبته ومعرفته وتوحيده، ويسمى ذلك «الشاهد» و«المثل الأعلى». فهي الشواهد','То, что пребывает в них, — не Сам Всевышний Господь и не Его атрибут, а знание о Нём, любовь к Нему, познание Его и исповедание Его единственности. Это называют «свидетельством» и «высшим подобием». Это свидетельства')])
p(545,[('والأمثلة العلمية التي قال الله تعالى فيها: {وَلَهُ الْمَثَلُ الْأَعْلَى فِي السَّمَاوَاتِ وَالْأَرْضِ وَهُوَ الْعَزِيزُ الْحَكِيمُ} [الروم: 27] وقال: {لِلَّذِينَ لَا يُؤْمِنُونَ بِالْآخِرَةِ مَثَلُ السَّوْءِ وَلِلَّهِ الْمَثَلُ الْأَعْلَى} [النحل: 60]. وكثيرا ما يقول الرجل لغيره: أنت في قلبي وفي فؤادي، والمراد هذا، لا ذاته ونفسه.','и образы знания, о которых Всевышний Аллах сказал: {وَلَهُ الْمَثَلُ الْأَعْلَى فِي السَّمَاوَاتِ وَالْأَرْضِ وَهُوَ الْعَزِيزُ الْحَكِيمُ} — «Ему принадлежит высшее подобие на небесах и на земле. Он — Могущественный, Мудрый» [«Ар-Рум», 30:27]; {لِلَّذِينَ لَا يُؤْمِنُونَ بِالْآخِرَةِ مَثَلُ السَّوْءِ وَلِلَّهِ الْمَثَلُ الْأَعْلَى} — «Тем, кто не верует в Последнюю жизнь, принадлежит дурное подобие, а Аллаху — высшее подобие» [«Ан-Нахль», 16:60]. Человек нередко говорит другому: «Ты в моём сердце, в моей душе», подразумевая именно это, а не саму его сущность.'),('قوله: (والذي يشار إليه على ألسنة المشيرين أنه إسقاط الحدث وإثبات القدم). إن أريد إسقاطه من الوجود، فمكابرة للعيان. وإن أريد به إسقاطه من الشهود، فليس ذلك بمأمور به، ولا هو كمال، فضلا عن أن يكون هو توحيد خاصة الخاصة. فما هذا الإسقاط للحدوث الذي هو نهاية التوحيد وأعلى مقاماته؟ وهل الكمال إلا أن يشهد الأشياء على ما هي عليه، كما هي في شهادة الحق سبحانه؟','Его слова: «То, на что указывают языки указывающих, — устранение возникшего и утверждение предвечного». Если имеется в виду устранить возникшее из существования, это упрямое отрицание очевидного. Если же имеется в виду устранить его из созерцания, это не предписано и не является совершенством, тем более единобожием избраннейших из избранных. Что же это за устранение возникшего, являющееся пределом единобожия и высочайшей его стоянкой? Разве совершенство не в том, чтобы созерцать вещи такими, каковы они есть, такими, каковы они в свидетельстве Пречистого Истинного?'),('فإسقاط الحدوث كلام لا حاصل له، إذ لا كمال فيه؛ بل إنما ينفع إسقاط الحدوث عن درجة القصد والتأله. فإسقاط الحدوث — كما تقدم — ثلاث مراتب: إسقاطه عن الوجود وهو مكابرة، وإسقاطه عن الشهود وهو نقص، وإسقاطه عن القصود وهو كمال.','Поэтому слова об устранении возникшего бессодержательны: в нём нет совершенства. Полезно лишь устранить возникшее из степени устремления и поклонения. Как уже говорилось, устранение возникшего имеет три степени: устранение его из существования — упрямое отрицание очевидного; устранение из созерцания — недостаток; устранение из устремлений — совершенство.'),('ولهذا قال الملحد: «إسقاط الحدوث وإثبات القدم صحيح في نظر الوارد على هذه الحضرة لضعفه، فإذا تمكن عرف أن الحدوث لم يزل ساقطا قط. فلا معنى لقوله: «إسقاط الحدوث»، ولا معنى لقوله: «إثبات','Поэтому безбожник сказал: «Устранение возникшего и утверждение предвечного верны с точки зрения вступившего в это присутствие ввиду его слабости. Когда же он утвердится, то узнает, что возникшее всегда было устранено. Поэтому слова “Устранение возникшего” бессмысленны, как и слова “Утверждение')])
p(546,[('القدم»، فإن القدم لم يزل ثابتا.','предвечного”, ведь предвечное всегда было утверждено».'),('فهذا الكلام لا يرضى به الموحد ولا الملحد، ولا أشار إليه القرآن الذي تضمن أعلى مراتب التوحيد؛ بل القرآن من أوله إلى آخره يدل على خلافه.','Эти слова не устраивают ни единобожника, ни безбожника. На них не указывает и Коран, заключающий высочайшие степени единобожия; напротив, от начала до конца Коран указывает на противоположное.'),('قال الملحد: وأيضا فإن التوحيد يستغرق القول في الطمس. فإن كان هناك نطق فليس هناك شهود، كما قال في «المواقف»: «أنا أقرب إلى اللسان من نطقه إذا نطق، فمن شهدني لم يذكرني، ومن ذكرني لم يشهد».','Безбожник сказал: «Кроме того, единобожие поглощает речь в стирании. Если там есть произнесение слов, там нет созерцания, как сказано в “Аль-Мавакиф”: “Я ближе к языку, чем его речь, когда он говорит. Кто созерцал Меня, не упомянул Меня, а кто упомянул Меня, не созерцал”».'),('قال: فقوله: «من ذكرني لم يشهد» هو نفس قول صاحب «المنازل»: «على أن هذا الرمز في ذلك التوحيد علة لا يصح ذلك التوحيد إلا بإسقاطها». وحقيقة ذلك: أنه لا يصح التوحيد إلا بإسقاط التوحيد، لأن ذلك الرمز والإشارة والخبر هو عن نفس التوحيد، فهو توحيد نطقي خبري مطابق للتوحيد المعلوم المخبر عنه. فإذا لم يصح التوحيد إلا بإسقاط ذلك كانت حقيقة الأمر أنه لا يصح التوحيد إلا بإسقاط التوحيد!','Он сказал: «Слова “Кто упомянул Меня, не созерцал” — то же самое, что слова автора “Маназил ас-саирин”: “Однако этот намёк в том единобожии — изъян, и то единобожие не будет верным без его устранения”». По сути это означает: единобожие не будет верным, пока не устранено единобожие. Ведь этот намёк, указание и сообщение относятся к самому единобожию. Это словесное, сообщаемое единобожие, соответствующее познанному единобожию, о котором сообщается. Если единобожие не будет верным без устранения этого, то выходит, что единобожие не будет верным без устранения единобожия!')])
p(547,[('ثم قال: (هذا قطب الإشارة إليه على ألسن علماء هذا الطريق، وإن زخرفوا له نعوتا، وفصلوه فصولا). يعني: أن قولهم: «التوحيد هو إسقاط الحدث وإثبات القدم» هو قطب مدار الإشارات إلى التوحيد عند هذه الطائفة.','Затем он сказал: «Это ось указаний на него в речах учёных этого пути, хотя они и украшают его описаниями и разделяют на разделы». Это означает: их слова «Единобожие — устранение возникшего и утверждение предвечного» — ось, вокруг которой вращаются указания на единобожие у этой группы.'),('ومع هذا، فلا يصح التوحيد إلا بإسقاط ما قالوه. ولذلك قال: (فإن ذلك التوحيد تزيده العبارة خفاء، والصفة نفورا، والبسط صعوبة). فإنه إذا لم يصح إلا بإسقاط الإشارة والصفة والبسط كانت العبارة عنه لا تزيده إلا خفاء، ولا الصفة إلا نفارا، أي هروبا وذهابا، والبسط والإيضاح لا يزيده إلا صعوبة لكثرة الإشارات والعبارات.','И вместе с тем единобожие не будет верным без устранения того, что они сказали. Поэтому он сказал: «Ибо выражение делает то единобожие ещё более сокрытым, описание — ещё более ускользающим, а подробное изложение — ещё более трудным». Если оно не будет верным без устранения указания, описания и подробного изложения, то выражение его только усиливает его сокрытость, описание — ускользание, то есть бегство и уход, а подробное разъяснение лишь увеличивает трудность из-за множества указаний и выражений.'),('قوله: (وإلى هذا التوحيد شخص أهل الرياضة وأرباب الأحوال — أي تطلعت قلوبهم — وله قصد أهل التعظيم. وإياه عنى المتكلمون في عين الجمع. وعليه تصطلم الإشارات، ثم لم ينطق عنه لسان، ولم تشر إليه عبارة).','Его слова: «К этому единобожию устремились упражняющиеся и обладатели состояний — то есть к нему устремились их сердца; к нему направились почитающие величие. Его подразумевали рассуждавшие о самом существе собранности. При нём указания срезаются начисто; затем ни один язык не выразил его и ни одно выражение не указало на него».'),('فيقال: يالله العجب! ما هذا السر الذي ما تكلم الله به، ولا أشار إليه هو ولا رسوله، ولا نالته إشارة، ولا قامت به عبارة، ولا أشار إليه مكون، ولا','Ответим: поразительно! Что это за тайна, о которой Аллах не говорил, на которую не указали ни Он, ни Его Посланник, которой не достигло ни одно указание и которую не выразило ни одно выражение, на которую не указало ни одно творение и которую не')])
p(548,[('تعاطاه حين، ولا أقله سبب؟ فهذه العقول حاضرة، وهذه المعارف، وهذا كلام الله ورسوله، بل سائر كتب الله، وكلام سادات العارفين من الأمة، فما هذا الحق المحال به؟ وعلى من وقعت هذه الحوالة؟ فإنكم أحلتم بأمر لم ينطق عنه لسان، لم تشر إليه عبارة، ولا تعاطاه حين، ولا أقله سبب= فعلى من أحلتم بهذا الحق المجهول الذي لا سبيل إلى العلم به، ولا التعبير عنه، ولا الإشارة إليه!','охватил никакой срок и не понесла никакая причина? Вот перед нами разумы и познания, слова Аллаха и Его Посланника, все книги Аллаха и слова предводителей познавших из этой общины. Что это за истина, к которой нас отсылают? На кого обращена эта отсылка? Вы отослали к тому, о чём не говорил ни один язык, на что не указывало ни одно выражение, чего не охватил никакой срок и не понесла никакая причина. К кому же вы отослали с этой неизвестной истиной, к познанию которой нет пути, которую невозможно ни выразить, ни указать на неё!'),('وأين قوله: (ما وحد الواحد من واحد) من قوله تعالى: {شَهِدَ اللَّهُ أَنَّهُ لَا إِلَهَ إِلَّا هُوَ وَالْمَلَائِكَةُ وَأُولُو الْعِلْمِ قَائِمًا بِالْقِسْطِ} [آل عمران: 18]؟ فأخبر سبحانه أن الملائكة كلهم يوحدونه، وأن أولي العلم يوحدونه. وكذلك إخباره عن أنبيائه ورسله وأتباعهم أنهم وحدوه ولم يشركوا به شيئا، كما أخبر عن نوح ومن آمن معه، وعن جميع الرسل ومن تبعهم. بل أخبر سبحانه عن السماوات السبع والأرضين وما فيهن أنها تسبح بحمده توحيدا ومعرفة. فهل يصح أن يقال: ما وحده أحد من الرسل والأنبياء والمؤمنين، ولا سبح بحمده سماء ولا أرض ولا شيء؟','Как соотносятся его слова «Никто из единых не исповедал единственности Единого» со словами Всевышнего: {شَهِدَ اللَّهُ أَنَّهُ لَا إِلَهَ إِلَّا هُوَ وَالْمَلَائِكَةُ وَأُولُو الْعِلْمِ قَائِمًا بِالْقِسْطِ} — «Аллах засвидетельствовал, что нет божества, кроме Него, а также ангелы и обладающие знанием. Он поддерживает справедливость» [«Аль Имран», 3:18]? Пречистый сообщил, что все ангелы исповедуют Его единственность и что обладающие знанием исповедуют её. Так же Он сообщил о Своих пророках, посланниках и их последователях, что они исповедовали Его единственность и ничего не приобщали к Нему в сотоварищи, как Он сообщил о Нухе и уверовавших вместе с ним, обо всех посланниках и последовавших за ними. Более того, Пречистый сообщил о семи небесах, землях и всех, кто в них, что они прославляют Его хвалой, исповедуя единобожие и познавая Его. Разве верно говорить: никто из посланников, пророков и верующих не исповедал Его единственности и ни небо, ни земля, ни что-либо ещё не прославляли Его хвалой?'),('وأبطل من هذا أن يقال: كل من وحد الله من الأولين والآخرين جاحد له ولتوحيده، لا موحد له على الحقيقة، وأن نعت جميع الرسل والأنبياء وأتباعهم له إلحاد، وكل من نعته من الأولين والآخرين فهو لاحد! فلا معنى صحيح، ولا لفظ مليح، بل المعنى أبطل من اللفظ، واللفظ أقبح من المعنى!','Ещё ложнее говорить, что каждый из первых и последних, кто исповедал единственность Аллаха, отрицает Его и Его единобожие, а не является подлинным единобожником; что описание, которое дают Ему все посланники, пророки и их последователи, — уклонение и что всякий из первых и последних, кто описывает Его, — уклоняющийся! Здесь нет ни верного смысла, ни прекрасного выражения. Смысл ещё ложнее слов, а слова ещё безобразнее смысла!')])
merge('v4-p544-04','v4-p545-01');merge('v4-p545-04','v4-p546-01');merge('v4-p547-04','v4-p548-01')
D['boundary_notes']=[{'printed_page':539,'position':'start','note':'538 просмотрена для контекста.539 начинается самостоятельными пунктами9–10 списка, начатого538; абзацного переноса нет, слияние539-01 с538 не требуется.'},{'printed_page':548,'position':'end','note':'549 просмотрена для контекста; начинается новым самостоятельным абзацем «ثم يقال». Конец548 завершён; внешнее слияние не нужно.'}];save()
